$('#sheet-tab').onclick=()=>setView(false);$('#world-tab').onclick=()=>setView(true);$('.brand').onclick=e=>{e.preventDefault();setView(false)};$('#show-world').onclick=()=>{dialog.close();setView(true);nodes.forEach(n=>n.el.classList.toggle('selected',n.id===people[selected].id));nodes[selected].el.focus({preventScroll:true});nodes[selected].el.scrollIntoView({block:'nearest',inline:'nearest'})};
let nodes=[],edges=[],drag=null,initialized=false;
function ensureWorld(){if(initialized)return;initialized=true;const locations=people.map((_,i)=>[40+(i%6)*180,45+Math.floor(i/6)*190]);
people.forEach((p,i)=>{const [x,y]=locations[i]||[40+(i%6)*180,55+Math.floor(i/6)*190],el=document.createElement('button');el.className='node';el.setAttribute('aria-label',`${p.name}. Drag or use arrow keys to move. Enter to explore.`);el.innerHTML=`<canvas width="244" height="184" aria-hidden="true"></canvas><span>${p.name}</span><small>STUDY ${String(i+1).padStart(2,'0')}</small>`;const label=document.createElement('div');label.className='node-person';const face=portrait(p);if(face)label.append(face);label.append(el.querySelector('span'));el.insertBefore(label,el.querySelector('small'));$('#nodes').append(el);const n={id:p.id,x,y,homeX:x,homeY:y,vx:0,vy:0,el,canvas:el.querySelector('canvas')};nodes.push(n);el.addEventListener('pointerdown',e=>{if(e.button!==0)return;const r=$('#world').getBoundingClientRect();drag={n,dx:e.clientX-r.left-n.x,dy:e.clientY-r.top-n.y,startX:e.clientX,startY:e.clientY,moved:false};el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',e=>{if(drag?.n!==n)return;const r=$('#world').getBoundingClientRect();if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>4)drag.moved=true;if(drag.moved){n.x=Math.max(0,Math.min($('#world').clientWidth-136,e.clientX-r.left-drag.dx));n.y=Math.max(0,Math.min(750,e.clientY-r.top-drag.dy));n.vx=n.vy=0;renderWorld()}});el.addEventListener('pointerup',()=>{if(drag?.n!==n)return;el.dataset.dragged=String(drag.moved);drag=null});el.addEventListener('pointercancel',()=>{drag=null;el.dataset.dragged='true'});el.onclick=()=>{if(el.dataset.dragged==='true'){el.dataset.dragged='false';return}openPerson(i)};el.addEventListener('keydown',e=>{const dirs={ArrowLeft:[-25,0],ArrowRight:[25,0],ArrowUp:[0,-25],ArrowDown:[0,25]};if(dirs[e.key]){e.preventDefault();n.x=Math.max(0,Math.min($('#world').clientWidth-136,n.x+dirs[e.key][0]));n.y=Math.max(0,Math.min(750,n.y+dirs[e.key][1]));renderWorld()}})});
connections.forEach(e=>{const a=nodes.find(n=>n.id===e.a),b=nodes.find(n=>n.id===e.b),line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('stroke','#85857e');line.setAttribute('stroke-width','1.3');if(e.type.startsWith('Technique'))line.setAttribute('stroke-dasharray','5 5');$('#threads').append(line);edges.push({a,b,line,length:Math.hypot(a.x-b.x,a.y-b.y)});const card=document.createElement('article');card.className='evidence';card.innerHTML=`<div class="type">${e.type}</div><h3>${people.find(p=>p.id===e.a).name} ↔ ${people.find(p=>p.id===e.b).name}</h3><p>${e.label}</p>`;card.append(link(e.source,e.url));$('#evidence').append(card)});renderWorld()}
function stepWorld(){for(const e of edges){let dx=e.b.x-e.a.x,dy=e.b.y-e.a.y,d=Math.hypot(dx,dy)||1,f=(d-e.length)*.007;const fx=dx/d*f,fy=dy/d*f;e.a.vx+=fx;e.a.vy+=fy;e.b.vx-=fx;e.b.vy-=fy}for(let i=0;i<nodes.length;i++)for(let j=0;j<i;j++){let a=nodes[i],b=nodes[j],dx=a.x-b.x,dy=a.y-b.y;if(Math.abs(dx)<150&&Math.abs(dy)<150){let d=Math.hypot(dx,dy)||1,f=(150-Math.min(150,d))*.012;a.vx+=dx/d*f;b.vx-=dx/d*f;a.vy+=dy/d*f;b.vy-=dy/d*f}}for(const n of nodes){if(drag?.n===n)continue;n.vx+=(n.homeX-n.x)*.0007;n.vy+=(n.homeY-n.y)*.0007;n.vx*=.86;n.vy*=.86;n.x=Math.max(0,Math.min($('#world').clientWidth-136,n.x+n.vx));n.y=Math.max(0,Math.min(750,n.y+n.vy))}renderWorld()}
function renderWorld(){nodes.forEach(n=>n.el.style.transform=`translate(${n.x}px,${n.y}px)`);edges.forEach(e=>{e.line.setAttribute('x1',e.a.x+68);e.line.setAttribute('y1',e.a.y+60);e.line.setAttribute('x2',e.b.x+68);e.line.setAttribute('y2',e.b.y+60)})}
$('#reset').onclick=()=>{nodes.forEach(n=>{n.x=n.homeX;n.y=n.homeY;n.vx=n.vy=0;n.el.classList.remove('selected')});renderWorld()};
